     Object.entries(state.steps)
       .flatMap(([id, step]) => (step.status === 'running' && step.startedAt !== undefined ? [{ id, startedAt: step.startedAt }] : []))
       .at(0);
D4 tools/dpf/src/follow/ledger.ts (new):
   import { closeSync, existsSync, fstatSync, openSync, readSync } from 'node:fs';

   export interface StepEvent { readonly at: string | undefined; readonly stepId: string | undefined; readonly status: string | undefined; readonly detail: string | undefined; readonly exitCode: number | undefined; readonly notes: readonly string[] | undefined }
   export interface ResidueRow { readonly runId: string | undefined; readonly stage: string | undefined; readonly entry: unknown }
   export interface LedgerPoll { readonly events: StepEvent[]; readonly residue: ResidueRow[]; readonly errors: string[] }

   interface LedgerRow { readonly kind?: string; readonly at?: string; readonly stepId?: string; readonly status?: string; readonly detail?: string; readonly exitCode?: number; readonly notes?: string[]; readonly runId?: string; readonly stage?: string; readonly entry?: unknown }

   const NEWLINE = 0x0a;

   const emptyPoll = (): LedgerPoll => ({ events: [], residue: [], errors: [] });

   /** The ledger's bytes from `offset` on; none when the file is not there yet. */
   const tailBytes = (file: string, offset: number): Buffer => {
     if (!existsSync(file)) return Buffer.alloc(0);
     const fd = openSync(file, 'r');
     try {
       const bytes = Buffer.alloc(Math.max(0, fstatSync(fd).size - offset));
       readSync(fd, bytes, 0, bytes.length, offset);
       return bytes;
     } finally {
       closeSync(fd);
     }
   };

   const parseRow = (line: string): LedgerRow | undefined => {
     try {
       const value: unknown = JSON.parse(line);
       return typeof value === 'object' && value !== null ? (value as LedgerRow) : undefined;
     } catch {
       return undefined;
     }
   };

   const stepEvent = (row: LedgerRow): StepEvent => ({ at: row.at, stepId: row.stepId, status: row.status, detail: row.detail, exitCode: row.exitCode, notes: row.notes });

   const withLine = (poll: LedgerPoll, line: string): LedgerPoll => {
     const row = parseRow(line);
     if (row === undefined) return { ...poll, errors: [...poll.errors, line] };
     if (row.kind === 'step') return { ...poll, events: [...poll.events, stepEvent(row)] };
     if (row.kind === 'residue') return { ...poll, residue: [...poll.residue, { runId: row.runId, stage: row.stage, entry: row.entry }] };
     return poll;
   };

   export const ledgerTail = (file: string, start: number): { poll(): LedgerPoll } => {
     const cursor = { offset: start };
     return {
       poll(): LedgerPoll {
         const bytes = tailBytes(file, cursor.offset);
         const end = bytes.lastIndexOf(NEWLINE);
         if (end === -1) return emptyPoll();
         cursor.offset += end + 1;
         return bytes.subarray(0, end).toString('utf8').split('\n').filter(line => line !== '').reduce(withLine, emptyPoll());
       },
     };
   };
   `start` and the offset are BYTES. A partial last line (no trailing newline) is NOT included
   in this poll: the offset stops after the last 0x0a, so it waits for the next poll and is
   never decoded half-way through a multi-byte character. An unparsable line (non-JSON, or
   JSON that is not an object) becomes ONE errors[] entry and reading continues. Only
   kind: 'step' and kind: 'residue' rows are kept; other kinds are ignored. Only the bytes
