function extractChunks(parentNode, isPartOfChunk) {
  const chunks = [];
  let chunk = [];
  let lastNode = undefined;

  for (const node of parentNode.body) {
    const result = isPartOfChunk(node, lastNode);
    switch (result) {
      case "PartOfChunk":
        chunk.push(node);
        break;

      case "PartOfNewChunk":
        if (chunk.length > 0) {
          chunks.push(chunk);
        }
        chunk = [node];
        break;

      case "NotPartOfChunk":
        if (chunk.length > 0) {
          chunks.push(chunk);
          chunk = [];
        }
        break;

      /* v8 ignore start */
      default:
        throw new Error(`Unknown chunk result: ${result}`);
      /* v8 ignore stop */
    }

    lastNode = node;
  }

  if (chunk.length > 0) {
    chunks.push(chunk);
  }

  return chunks;
}

