const runValidate = (deps: IrCommandDeps, flags: IrFlags): Outcome => {
  const file = required(flags, 'file');
  const doc = deps.readIr(kindOf(flags), file);
  return doc.ok ? { code: EXIT_OK } : refusedIssues('ir validate', file, doc.issues);
};

interface Edit {
  readonly gate: string;
  readonly kind: IrKind;
  readonly file: string;
  readonly apply: (doc: unknown) => PatchApplication;
}

/** Apply, validate the WHOLE result, and only then write — a refusal never touches the file. */
const commitEdit = (deps: IrCommandDeps, edit: Edit): Outcome => {
  const current = deps.readIr(edit.kind, edit.file);
  if (!current.ok) return refusedIssues(edit.gate, edit.file, current.issues);
  const applied = edit.apply(current.value);
  if (!applied.ok) return refusedErrors(edit.gate, edit.file, applied.errors);
  const checked = parseIrWith(IR_KINDS[edit.kind], JSON.stringify(applied.doc), edit.file);
  if (!checked.ok) return refusedIssues(edit.gate, edit.file, checked.issues);
  deps.writeIr(edit.kind, edit.file, checked.value);
  return { code: EXIT_OK };
};

const appendAt = (arrayPath: string, value: unknown) => (doc: unknown): PatchApplication => {
  const slice = sliceAt(doc, arrayPath);
  if (!slice.ok) return { ok: false, errors: [slice.error] };
  return isArray(slice.value)
    ? applyOps(doc, [{ op: 'add', jsonPath: `${arrayPath}[${slice.value.length}]`, value }])
    : { ok: false, errors: [`${arrayPath}: append target is not an array`] };
};

const editOf = (flags: IrFlags, gate: string, apply: Edit['apply']): Edit => ({ gate, kind: kindOf(flags), file: required(flags, 'file'), apply });

const runSet = (deps: IrCommandDeps, flags: IrFlags): Outcome => {
  const op: IrPatchOp = { op: 'replace', jsonPath: required(flags, 'path'), value: valueFlagOf(deps, flags) };
  return commitEdit(deps, editOf(flags, 'ir set', doc => applyOps(doc, [op])));
};

const runAppend = (deps: IrCommandDeps, flags: IrFlags): Outcome =>
  commitEdit(deps, editOf(flags, 'ir append', appendAt(required(flags, 'path'), valueFlagOf(deps, flags))));

const runPatch = (deps: IrCommandDeps, flags: IrFlags): Outcome => {
  const ops = opsOf(deps, flags);
  return commitEdit(deps, editOf(flags, 'ir patch', doc => applyOps(doc, ops)));
};

