interface ExpectReturn {
  toEqual(expected: unknown): void;
  toBe(expected: unknown): void;
  toBeUndefined(): void;
  toBeTrue(): void;
  toBeFalse(): void;
  rejects: { toThrow(message: string): void };
}
declare const expectFn: ((actual: unknown) => ExpectReturn) & {
  stringMatching(re: RegExp): unknown;
};
export declare const expect: typeof expectFn;
export declare function it(name: string, fn: () => void | Promise<void>): void;
export declare function describe(name: string, fn: () => void): void;
export declare function beforeEach(fn: () => void): void;
export declare function afterEach(fn: () => void): void;

// PROBE-ONLY: eslint without fix — prints every message (rule, line, severity).
const { ESLint } = require('/home/dev/work/dippe/dpf-bench-replay/node_modules/eslint');
