119	        : state.phase === 'replace-wait' ? replaceNext(state, line)
120	          : summaryNext(state, line);
121	  return { start: { state: initial, out: mainOut(initial) }, next };
122	};
123	
124	export const applyResolve = async (
125	  result: ResolveResult,
126	  record: PausePayload,
127	  cli: readonly string[],
128	): Promise<void> => {
129	  if (result.kind !== 'accept') return;
130	  const runWrite = async (write: GoalWrite): Promise<void> => {
131	    const r = await irSet({ cli, kind: 'goals', file: record.inputs.goals, path: write.path, value: write.value });
132	    if (!r.ok) {
133	      throw new Error(
134	        r.findings !== undefined
135	          ? `ir refused ${record.inputs.goals}: ${r.findings}`
136	          : `ir error ${record.inputs.goals}: ${r.error}`,
137	      );
138	    }
139	  };
140	  await result.writes.reduce((chain, write) => chain.then(() => runWrite(write)), Promise.resolve());
141	  cpSync(record.inputs.template, record.outputs[0]);
142	};
143	
144	const inCutStage = (row: ResidueRow, runId: string): boolean => row.runId === runId && row.stage === CUT_STAGE;
145	const cutEntry = (row: ResidueRow): ResidueEntry | undefined => {
146	  const parsed = ResidueEntrySchema.safeParse(row.entry);
147	  if (!parsed.success) return undefined;
148	  return parsed.data.anchor.jsonPath === CUT_ANCHOR ? parsed.data : undefined;
149	};
150	export const resolveCuts = (rows: readonly ResidueRow[], runId: string): readonly string[] =>
151	  rows.filter((row) => inCutStage(row, runId)).map((row) => cutEntry(row)).filter((e): e is ResidueEntry => e !== undefined).map((e) => e.text);
