18	const WALK_SUMMARY_PROMPT = 'goals updated (w to write, q to abort)';
19	const NO_GOAL_LINE = 'every goal was dropped: keep or replace at least one (q to drop the edits)';
20	
21	export interface ResolveConfirmInput {
22	  readonly resolution: ResolutionIr;
23	  readonly goals: GoalsDoc;
24	  readonly cuts: readonly string[];
25	  readonly diffLines: readonly string[] | undefined;
26	}
27	export type GoalWrite =
28	  | { readonly path: '$.goals'; readonly value: readonly GoalEntry[] }
29	  | { readonly path: '$.nonGoals'; readonly value: readonly NonGoalEntry[] };
30	export type ResolveResult =
31	  | { readonly kind: 'accept'; readonly writes: readonly GoalWrite[] }
32	  | { readonly kind: 'correction' }
33	  | { readonly kind: 'quit' };
34	interface ResolveState {
35	  readonly phase: 'main' | 'walk' | 'replace-wait' | 'walk-summary';
36	  readonly index: number;
37	  readonly goals: readonly GoalEntry[];
38	  readonly nonGoals: readonly NonGoalEntry[];
39	  readonly walked: readonly (GoalEntry | NonGoalEntry | undefined)[];
40	  readonly writes: readonly GoalWrite[];
41	}
42	
43	export const resolveConfirmScreen = (input: ResolveConfirmInput): Screen<ResolveState, ResolveResult> => {
44	  const { resolution, goals, cuts, diffLines } = input;
45	  const total = goals.goals.length + goals.nonGoals.length;
46	  const entryAt = (index: number): GoalEntry | NonGoalEntry =>
47	    index < goals.goals.length ? goals.goals[index] : goals.nonGoals[index - goals.goals.length];
48	  const promptAt = (index: number): string => `${entryAt(index).id}: ${entryAt(index).text} (Enter keep, r replace, d drop)`;
49	  const mainOut = (state: ResolveState): readonly string[] => [
50	    `shape: ${resolution.shape}`,
51	    ...[...resolution.mapping]
52	      .sort((a, b) => Number(b.kind === 'unknown') - Number(a.kind === 'unknown'))
53	      .map(m => `${m.noun}: ${m.kind}${m.path === null ? '' : ` ${m.path}`}`),
54	    ...[...resolution.drift]
55	      .sort((a, b) => Number(b.status === 'unclear') - Number(a.status === 'unclear'))
56	      .map(d => `${d.id}: ${d.status}`),
57	    `blast: ${resolution.blastRadius.join(', ')}`,
58	    ...state.goals.map(g => `${g.id}: ${g.text}`),
59	    ...state.nonGoals.map(n => `${n.id}: ${n.text}`),
60	    ...cuts.map(c => `cut: ${c}`),
61	    ...(diffLines ?? []),
62	    MAIN_PROMPT,
63	  ];
64	  const initial: ResolveState = { phase: 'main', index: 0, goals: goals.goals, nonGoals: goals.nonGoals, walked: [], writes: [] };
65	  const rebuild = (state: ResolveState): Pick<ResolveState, 'goals' | 'nonGoals' | 'writes'> => {
66	    const newGoals = state.walked.slice(0, goals.goals.length).filter((e): e is GoalEntry => e !== undefined);
67	    const newNonGoals = state.walked.slice(goals.goals.length).filter((e): e is NonGoalEntry => e !== undefined);
68	    const writes: GoalWrite[] = [{ path: '$.goals', value: newGoals }];
69	    if (JSON.stringify(newNonGoals) !== JSON.stringify(goals.nonGoals)) writes.push({ path: '$.nonGoals', value: newNonGoals });
70	    return { goals: newGoals, nonGoals: newNonGoals, writes };
71	  };
72	  const doneFor = (line: string): ResolveResult | undefined =>
73	    line === 'c' ? { kind: 'correction' } : line === 'q' ? { kind: 'quit' } : undefined;
74	  const mainNext = (state: ResolveState, line: string): Turn<ResolveState, ResolveResult> => {
75	    if (line === 'g') return { state: { ...state, phase: 'walk', index: 0, walked: [] }, out: [promptAt(0)] };
76	    if (line === 'a') return { state, out: [], result: { kind: 'accept', writes: state.writes } };
77	    const done = doneFor(line);
78	    if (done !== undefined) return { state, out: [], result: done };
79	    return { state, out: mainOut(state) };
80	  };
81	  const walkNext = (state: ResolveState, line: string): Turn<ResolveState, ResolveResult> => {
82	    const advance = (decision: GoalEntry | NonGoalEntry | undefined): Turn<ResolveState, ResolveResult> => {
83	      const nextIndex = state.index + 1;
84	      const nextPhase = nextIndex >= total ? 'walk-summary' as const : 'walk' as const;
85	      return {
86	        state: { ...state, phase: nextPhase, index: nextIndex, walked: [...state.walked, decision] },
87	        out: nextPhase === 'walk-summary' ? [WALK_SUMMARY_PROMPT] : [promptAt(nextIndex)],
88	      };
89	    };
90	    if (line === '') return advance(entryAt(state.index));
91	    if (line === 'r') return { state: { ...state, phase: 'replace-wait' }, out: ['new text:'] };
92	    if (line === 'd') return advance(undefined);
93	    return { state, out: [promptAt(state.index)] };
94	  };
95	  const replaceNext = (state: ResolveState, line: string): Turn<ResolveState, ResolveResult> => {
