    expect(calls()).toEqual([
      ['ir', 'set', '--kind', 'goals', '--file', '/r/goals.json', '--path', '$.goals', '--value', expect.stringMatching(/^@/u)],
      ['ir', 'set', '--kind', 'goals', '--file', '/r/goals.json', '--path', '$.nonGoals', '--value', expect.stringMatching(/^@/u)],
